tasks.solution:
class FuelTank {
  constructor(capacity) {
    this.capacity = capacity;
    this.amount = capacity;
  }

  use(liters) {
    // yeterliyse düş ve true, değilse false
    if (liters > this.amount) return false;
    this.amount -= liters;
    return true;
  }

  get percent() {
    // yüzde kaç dolu?
    return Math.round((this.amount / this.capacity) * 100);
  }
}

const tank = new FuelTank(200);
tank.use(50);
console.log("Doluluk: %" + tank.percent);

check.js:
const t = new FuelTank(200);
assert(t.use(50) === true && t.amount === 150, "use(50) true döndürmeli ve amount 150 olmalı.");
const d = Object.getOwnPropertyDescriptor(FuelTank.prototype, "percent");
assert(d && typeof d.get === "function", "percent bir getter olmalı: get percent() { ... }");
assert(t.percent === 75, "150/200 için percent 75 olmalı.");
assert(t.use(500) === false && t.amount === 150, "Yetmeyen yakıt istenince false döndürmeli ve amount değişmemeli.");
assert(t.use(150) === true && t.percent === 0, "Depo boşalınca percent 0 olmalı.");
assert(_lines.includes("Doluluk: %75"), "Çıktıda 'Doluluk: %75' görünmeli.");

