const a = new Astronaut("Mert");
assert(a.id === 4 && Astronaut.count === 4 && a.badge() === "#4 Mert", "Yeni astronot 4 numarayı almalı: '#4 Mert'.");
assert(a.count === undefined, "count örneğe değil sınıfa ait olmalı (static).");
const list = Astronaut.fromList(["X", "Y"]);
assert(Array.isArray(list) && list.length === 2 && list[1] instanceof Astronaut && list[1].id === 6, "fromList her ad için yeni bir Astronaut üretmeli.");

