const canvas = document.querySelector("#game");
const ctx = canvas.getContext("2d");
const SHIP_SIZE = 30;

class Ship {
  constructor(x, y) {
    this.x = x;
    this.y = y;
  }

  move(dx) {
    const maxX = canvas.width - SHIP_SIZE;
    this.x = Math.min(maxX, Math.max(0, this.x + dx));
  }

  hits(star) {
    const insideX = star.x >= this.x && star.x <= this.x + SHIP_SIZE;
    const insideY = star.y >= this.y && star.y <= this.y + SHIP_SIZE;
    return insideX && insideY;
  }

  draw() {
    ctx.fillStyle = "#f7df1e";
    ctx.fillRect(this.x, this.y, SHIP_SIZE, SHIP_SIZE);
  }
}

const ship = new Ship(135, 110);

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ship.draw();
}

document.addEventListener("keydown", (e) => {
  if (e.key === "ArrowLeft") ship.move(-10);
  if (e.key === "ArrowRight") ship.move(10);
  render();
});

render();

check.js:
assert(ship.x === 135 && ship.y === 110, "constructor x ve y'yi kaydetmeli: ship.x 135, ship.y 110.");
key("ArrowRight");
assert(ship.x === 145, "Sağ oka basınca gemi 10 piksel sağa gitmeli (move).");
const [r, g, b] = pixel("#game", 160, 125);
assert(r === 247 && g === 223 && b === 30, "Gemi yeni konumunda sarı (#f7df1e) çizilmeli.");
const s = new Ship(0, 0);
s.move(-20);
assert(s.x === 0, "move gemiyi 0'ın soluna götürmemeli.");
s.move(1000);
assert(s.x === 270, "move gemiyi sağ kenardan dışarı çıkarmamalı (en çok 300 - 30 = 270).");
s.move(-100);
assert(s.x === 170, "move(-100) sonrası x 170 olmalı.");
const t = new Ship(100, 50);
assert(t.hits({ x: 110, y: 60 }) === true && t.hits({ x: 100, y: 50 }) === true && t.hits({ x: 130, y: 80 }) === true, "Karenin içindeki ya da kenarındaki yıldız için hits true olmalı.");
assert(t.hits({ x: 131, y: 60 }) === false && t.hits({ x: 110, y: 81 }) === false && t.hits({ x: 99, y: 60 }) === false, "Karenin dışındaki yıldız için hits false olmalı.");

