class ProjectCard {
  constructor(title, tech, url) {
    this.title = title;
    this.tech = tech;
    this.url = url;
  }

  render() {
    const card = document.createElement("article");
    card.className = "card";
    const h3 = document.createElement("h3");
    h3.textContent = this.title;
    const tech = document.createElement("p");
    tech.className = "tech";
    tech.textContent = this.tech.join(", ");
    const link = document.createElement("a");
    link.href = this.url;
    link.textContent = "İncele";
    card.append(h3, tech, link);
    return card;
  }
}

const myProjects = [
  new ProjectCard("Yıldız Avcısı", ["Canvas", "JavaScript"], "#oyun"),
  new ProjectCard("Hava Durumu", ["fetch", "JSON"], "#hava"),
  new ProjectCard("Not Defteri", ["localStorage"], "#notlar"),
];

const box = document.querySelector("#projects");
// her kartın render() sonucunu box'a ekle
myProjects.forEach((project) => box.append(project.render()));

check.js:
const cards = $$("#projects .card");
assert(cards.length === 3, "#projects içinde 3 tane .card olmalı.");
const h3 = cards[0].querySelector("h3");
assert(h3 && h3.textContent.trim() === "Yıldız Avcısı", "İlk kartın <h3>'ü 'Yıldız Avcısı' olmalı.");
const tech = cards[0].querySelector(".tech");
assert(tech && tech.textContent.trim() === "Canvas, JavaScript", "p.tech 'Canvas, JavaScript' olmalı.");
const a = cards[0].querySelector("a");
assert(a && a.getAttribute("href") === "#oyun" && a.textContent.trim() === "İncele", "Kartta href'i '#oyun' olan, metni 'İncele' olan bir <a> olmalı.");
const el = new ProjectCard("Test", ["A", "B", "C"], "#t").render();
assert(el && el.tagName === "ARTICLE" && el.classList.contains("card"), "render() bir <article class=\"card\"> döndürmeli.");
assert(el.querySelector(".tech").textContent.trim() === "A, B, C", "Teknolojiler 'A, B, C' biçiminde birleştirilmeli.");

