class Task {
  constructor(title) {
    this.title = title;
    this.done = false;
  }

  toggle() {
    this.done = !this.done;
  }

  get label() {
    const box = this.done ? "[x]" : "[ ]";
    return `${box} ${this.title}`;
  }
}

const tasks = [new Task("Matematik ödevi"), new Task("Fizik tekrarı"), new Task("Kitap okuma")];
const list = document.querySelector("#tasks");

function render() {
  list.innerHTML = "";
  tasks.forEach((task) => {
    const li = document.createElement("li");
    li.textContent = task.label;
    li.classList.toggle("done", task.done === true);
    li.addEventListener("click", () => {
      task.toggle();
      render();
    });
    list.append(li);
  });
  const left = tasks.filter((t) => !t.done).length;
  document.querySelector("#count").textContent = `${left} görev kaldı`;
}

render();

check.js:
const t = new Task("Deneme");
assert(t.title === "Deneme" && t.done === false, "Yeni görevin title'ı kaydedilmeli, done false olmalı.");
assert(t.label === "[ ] Deneme", "Bitmemiş görevin label'ı '[ ] Deneme' olmalı.");
t.toggle();
