assert(li.textContent === "[x] Fizik tekrarı" && li.classList.contains("done"), "Bir göreve tıklayınca '[x] Fizik tekrarı' olmalı.");
assert($("#count").textContent === "2 görev kaldı", "#count '2 görev kaldı' olmalı.");

