const questions = [
  { soru: "Ay, hangi gezegenin uydusudur?", secenekler: ["Mars", "Dünya", "Jüpiter"], dogru: 1 },
  { soru: "Kızıl gezegen olarak bilinen gezegen hangisidir?", secenekler: ["Mars", "Venüs", "Merkür"], dogru: 0 },
];

class Quiz {
  constructor(questions) {
    this.questions = questions;
    this.current = 0;
    this.score = 0;
  }

  get question() {
    return this.questions[this.current];
  }

  answer(index) {
    const correct = index === this.question.dogru;
    if (correct) this.score += 10;
    return correct;
  }

  next() {
    this.current += 1;
  }

  get isOver() {
    return this.current >= this.questions.length;
  }
}

const quiz = new Quiz(questions);
console.log(quiz.question.soru, quiz.answer(1));
quiz.next();
console.log(quiz.question.soru, quiz.answer(2));
quiz.next();
console.log("Bitti mi?", quiz.isOver, "| Puan:", quiz.score);

check.js:
assert(_lines.includes("Bitti mi? true | Puan: 10"), "Çıktının son satırı 'Bitti mi? true | Puan: 10' olmalı.");
const q = new Quiz([{ soru: "A", secenekler: ["x", "y"], dogru: 0 }, { soru: "B", secenekler: ["x", "y"], dogru: 1 }]);
assert(q.isOver === false, "Başlangıçta isOver false olmalı.");
assert(q.answer(0) === true && q.score === 10, "Doğru cevapta answer true döndürmeli ve score 10 artmalı.");
q.next();
assert(q.current === 1 && q.question.soru === "B", "next() sonraki soruya geçmeli.");
assert(q.answer(0) === false && q.score === 10, "Yanlış cevapta answer false döndürmeli, score değişmemeli.");
q.next();
assert(q.isOver === true, "Son sorudan sonra isOver true olmalı.");
